#include "cache/core/cache_config.h"

#include <stdexcept>
#include <string>

namespace tokenspeed {

void CacheGroupConfig::Validate() const {
    ValidateCapacityInputs();
    if (total_pages < 1) {
        throw std::invalid_argument("Cache group '" + group_id + "': total_pages must include the null page");
    }
}

void CacheGroupConfig::ValidateCapacityInputs() const {
    if (group_id.empty()) {
        throw std::invalid_argument("CacheGroupConfig: group_id must be non-empty");
    }
    // Every remaining message names the group: a model mixes several of them,
    // and the offending one is the only actionable part of the diagnostic.
    const std::string where = "Cache group '" + group_id + "': ";
    if (attn_kind == AttnKind::kState) {
        if (block_granularity != 0) {
            throw std::invalid_argument(where +
                                        "a State group has no token span: block_granularity must be 0 (its two "
                                        "slots hold whole recurrent states, not token rows)");
        }
    } else if (block_granularity <= 0) {
        throw std::invalid_argument(where + "block_granularity must be > 0");
    }
    if (cache_blocks_per_lcm_block <= 0) {
        throw std::invalid_argument(where + "cache_blocks_per_lcm_block must be > 0");
    }
    if (shard_count <= 0 || cache_blocks_per_lcm_block % shard_count != 0) {
        throw std::invalid_argument(where + "shard_count must be positive and divide parent packing");
    }
    if (attn_kind == AttnKind::kSlidingWindow) {
        if (!sliding_window_tokens || *sliding_window_tokens <= 0) {
            throw std::invalid_argument(where + "sliding_window_tokens must be > 0 for sliding groups");
        }
    } else if (sliding_window_tokens) {
        throw std::invalid_argument(where + "only a sliding-window group carries sliding_window_tokens");
    }
    if (checkpoint_granularity < 1 || (attn_kind != AttnKind::kState && checkpoint_granularity != 1)) {
        throw std::invalid_argument(where + "checkpoint_granularity requires a positive state-group grain");
    }
    if (replayable && attn_kind != AttnKind::kSlidingWindow) {
        throw std::invalid_argument(where +
                                    "only a sliding-window group can be regenerated by bounded replay; a "
                                    "full-history group is prefix-closed and shared, a state group is a checkpoint");
    }
}

}  // namespace tokenspeed
